PAGES=[]
def page(path,title,desc,body,crumbs=[],schema=None,index=True):
    title,desc=metadata(path,title,desc,SERVICES,CITIES)
    # Convert legacy zone selectors into real, linked neighborhood pages.
    text_links={}
    for city in CITIES:
        for zone in city['zones']:
            old='/zones/'+city['slug']+'/?secteur='+slug(zone)
            text_links[old]='/zones/'+city['slug']+'/'+slug(zone)+'/'
            for service in SERVICES:
                text_links['/zones/'+city['slug']+'/'+service['slug']+'/?secteur='+slug(zone)]='/zones/'+city['slug']+'/'+slug(zone)+'/'+service['slug']+'/'
    def rewrite_links(value):
        return re.sub(r'href="([^"]+)"',lambda m:'href="'+text_links.get(m.group(1),m.group(1))+'"',value)
    body=rewrite_links(body)
    url=ORIGIN+path
    bc=[('Accueil','/')]+crumbs
    breadcrumb='' if not crumbs else '<nav class="crumb wrap" aria-label="Fil d’Ariane">'+'<span>/</span>'.join('<a href="'+p+'">'+e(n)+'</a>' for n,p in bc)+'</nav>'
    graph=[{'@type':'Organization','@id':ORIGIN+'/#organisation','name':'REPAREO','email':'info@repareo.ma','telephone':'+212707072297','contactPoint':[{'@type':'ContactPoint','telephone':n,'contactType':'customer service','availableLanguage':'French'} for n in ['+212707072297','+212712123112']],'url':ORIGIN+'/', 'logo':ORIGIN+'/assets/logo.webp','areaServed':[{'@type':'Place','name':c['name']} for c in CITIES if c['zones']]}]
    if crumbs:graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':ORIGIN+p} for i,(n,p) in enumerate(bc)]})
    graph.append({'@type':'WebSite','@id':ORIGIN+'/#website','url':ORIGIN+'/','name':'REPAREO','inLanguage':'fr-MA','publisher':{'@id':ORIGIN+'/#organisation'}})
    graph.append({'@type':'WebPage','@id':url+'#webpage','url':url,'name':title,'description':desc,'inLanguage':'fr-MA','isPartOf':{'@id':ORIGIN+'/#website'}})
    if schema:
        schema=dict(schema)
        schema['@id']=url+'#'+schema['@type'].lower()
        schema['url']=url
        if schema['@type']=='Article':
            schema['inLanguage']='fr-MA'
            schema['mainEntityOfPage']={'@id':url+'#webpage'}
            image_match=re.search(r'<img src="(/assets/[^"]+)"',body)
            if image_match:schema['image']=ORIGIN+image_match.group(1)
        graph.append(schema)
    home_css='<link rel="stylesheet" href="/home.css">' if path=='/' else ''
    text='<!doctype html><html lang="fr-MA"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="'+e(CSP)+'"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+' | REPAREO</title><meta name="description" content="'+e(desc)+'"><meta name="robots" content="'+('index,follow' if index else 'noindex,follow')+'"><link rel="canonical" href="'+url+'"><meta name="theme-color" content="#102c3c"><meta property="og:title" content="'+e(title)+' | REPAREO"><meta property="og:description" content="'+e(desc)+'"><meta property="og:type" content="'+('article' if schema and schema.get('@type')=='Article' else 'website')+'"><meta property="og:url" content="'+url+'"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="/style.css">'+home_css+'<link rel="stylesheet" href="/modern.css"><script defer src="/app.js"></script><script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('</','<\\/')+'</script></head><body><a class="skip" href="#main">Aller au contenu</a><div class="topbar"><div class="wrap"><span>INSTALLATION · RÉPARATION · RÉNOVATION</span><span>Votre projet, partout au Maroc</span></div></div><header><div class="wrap navwrap">'+LOGO+'<button class="menubtn" aria-expanded="false" aria-controls="nav">Menu ☰</button><nav id="nav" aria-label="Navigation principale">'+rewrite_links(NAV)+'<a class="button small" href="/contact/">Parlons de votre projet <span>↗</span></a></nav></div></header>'+breadcrumb+'<main id="main">'+body+'</main>'+FOOT+contact_bar()+'</body></html>'
    target=D/('index.html' if path=='/' else path.strip('/')+'/index.html'); target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text,encoding='utf-8')
    if index:PAGES.append(path)
def pic(s,hero=False):
    return '<img src="/assets/'+s['slug']+'.webp" srcset="/assets/'+s['slug']+'-small.webp 480w, /assets/'+s['slug']+'.webp 1200w" sizes="(max-width:700px) 100vw, '+('50vw' if hero else '33vw')+'" width="1200" height="800" alt="Illustration d’un technicien REPAREO — '+s['name'].lower()+'" '+('fetchpriority="high"' if hero else 'loading="lazy"')+' decoding="async">'
def cards(city=None):
    return '<div class="servicegrid">'+''.join('<a class="servicecard" href="'+('/zones/'+city['slug']+'/'+s['slug']+'/' if city else '/services/'+s['slug']+'/')+'"><div class="cardphoto">'+pic(s)+'</div><div class="cardtext">'+service_icon(s['slug'])+'<h3>'+s['name']+'</h3><p>'+s['short']+'</p><span class="cardlink">Découvrir le service <b>↗</b></span></div></a>' for i,s in enumerate(SERVICES))+'</div>'
def heading(k,h,p):return '<section class="pageintro wrap"><div class="eyebrow">'+k+'</div><h1>'+h+'</h1><p class="lead">'+p+'</p></section>'
def citycards():return '<div class="citygrid">'+''.join('<a href="/zones/'+c['slug']+'/"><span class="cityindex">0'+str(i+1)+'</span><h3>'+c['name']+'</h3><p>'+str(len(c['zones']))+' quartiers et secteurs</p><span class="roundarrow">↗</span></a>' for i,c in enumerate(CITIES))+'</div>'
def questions(s,city=None):
    location=('en périphérie de Casablanca' if city['slug']=='peripherie-casablanca' else 'à '+city['name']) if city else 'dans votre secteur'
    attrs=(' data-question-area="'+e(city['name'])+'" data-question-location="'+e(location)+'"') if city else ''
    return '<section class="wrap service-questions"'+attrs+'><div class="eyebrow">VOS QUESTIONS</div><h2>Questions sur '+e(s['name'].lower())+' <span class="question-area-label">'+e(location)+'</span></h2><ol class="question-list">'+''.join('<li><span data-question-template="'+e(q)+'">'+e(q.replace('{lieu}',location))+'</span></li>' for q in QUESTIONS[s['slug']])+'</ol></section>'
def prestations(s):
    data=PRESTATIONS[s['slug']]
    return '<section class="wrap section prestations" aria-labelledby="prestations-title"><div class="sectionhead"><div><div class="eyebrow">EN DÉTAIL</div><h2 id="prestations-title">'+e(data['heading'])+'</h2></div></div><ul class="prestations-grid">'+''.join('<li><span class="prestation-number" aria-hidden="true">'+str(i+1).zfill(2)+'</span><h3>'+e(title)+'</h3><p>'+e(description)+'</p></li>' for i,(title,description) in enumerate(data['items']))+'</ul></section>'+task_links(s,SERVICES,PRESTATIONS,slug)
def cta():return '<section class="wrap cta"><div><div class="eyebrow">VOTRE PROCHAIN PROJET</div><h2>Un besoin dans votre maison ?<br>Commençons par le comprendre.</h2></div><a class="button light" href="/contact/">Préparer mon projet <span>↗</span></a></section>'
